/**
 * Server-side entitlement gate: renders `children` when the active
 * workspace is entitled to `feature`, and an upgrade prompt when it
 * isn't.
 *
 * A server component so gated content never reaches a browser that is
 * not entitled to it. It is still not authorization: the action or
 * route behind the feature must check for itself.
 *
 * What a locked feature is called, and which plan unlocks it, comes
 * from `@/lib/feature-catalog` — consumer-owned, because features are
 * product data. An unlisted feature still gates; it just falls back to
 * generic copy.
 */

import { getTranslations } from "next-intl/server";

import { getWorkspacePlan, hasFeature } from "@intelligo-dev/billing";
import {
  getDefaultProductSlug,
  getPlanBySlug,
} from "@intelligo-dev/billing/plans";

import { featureCatalog } from "@/lib/feature-catalog";
import { UpgradePrompt } from "./upgrade-prompt";

interface FeatureGateProps {
  workspaceId: string;
  /** Feature key, as registered with `registerProductFeatures`. */
  feature: string;
  children: React.ReactNode;
  /** Rendered instead of the default prompt when the gate closes. */
  fallback?: React.ReactNode;
  variant?: "full" | "compact";
}

export async function FeatureGate({
  workspaceId,
  feature,
  children,
  fallback,
  variant = "full",
}: FeatureGateProps) {
  if (await hasFeature(workspaceId, feature)) {
    return <>{children}</>;
  }

  if (fallback) {
    return <>{fallback}</>;
  }

  const t = await getTranslations("feature-gating");
  // Namespace-less: catalogue keys are fully qualified so a product can
  // point them at its own namespace.
  const tAny = await getTranslations();

  const descriptor = featureCatalog[feature];
  const currentPlanSlug = await getWorkspacePlan(workspaceId);

  // The plan catalogue is registered per product by the composition
  // root; `getDefaultProductSlug()` is the slug it set there.
  const product = getDefaultProductSlug();
  const planName = (slug: string) => getPlanBySlug(slug, product)?.name ?? slug;

  return (
    <UpgradePrompt
      feature={descriptor ? tAny(descriptor.labelKey) : t("genericFeature")}
      requiredPlan={
        descriptor?.requiredPlan
          ? planName(descriptor.requiredPlan)
          : t("genericPlan")
      }
      description={
        descriptor?.descriptionKey ? tAny(descriptor.descriptionKey) : undefined
      }
      currentPlan={planName(currentPlanSlug)}
      variant={variant}
    />
  );
}

"use client";

/**
 * What a closed `FeatureGate` renders: the feature's name, the plan
 * that unlocks it, and one way forward.
 *
 * `full` fills a page section, for a gate that replaces the whole
 * surface; `compact` fits a card or panel.
 */

import { ArrowUpRight, Lock } from "lucide-react";
import { useTranslations } from "next-intl";

import { Link } from "@/i18n/navigation";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { featureGatingConfig } from "@/lib/feature-gating-config";

interface UpgradePromptProps {
  /** Display name of the gated feature, already localized. */
  feature: string;
  /** Display name of the plan that unlocks it, already localized. */
  requiredPlan: string;
  description?: string;
  currentPlan?: string;
  variant?: "full" | "compact";
}

export function UpgradePrompt({
  feature,
  requiredPlan,
  description,
  currentPlan,
  variant = "full",
}: UpgradePromptProps) {
  const t = useTranslations("feature-gating");
  const compact = variant === "compact";

  return (
    <div
      className={
        compact ? "p-6" : "flex min-h-100 items-center justify-center p-6"
      }
    >
      <Card className="w-full max-w-md text-center">
        <CardHeader>
          <div
            className={`mx-auto mb-4 flex items-center justify-center rounded-full bg-muted ${
              compact ? "size-8" : "size-12"
            }`}
          >
            <Lock className={compact ? "size-4" : "size-6"} aria-hidden />
          </div>
          <CardTitle className={compact ? "text-lg" : "text-xl"}>
            {t("prompt.title", { feature, plan: requiredPlan })}
          </CardTitle>
          <CardDescription>
            {description ??
              t("prompt.description", { feature, plan: requiredPlan })}
          </CardDescription>
        </CardHeader>
        <CardContent>
          {!compact && currentPlan ? (
            <p className="mb-4 text-sm text-muted-foreground">
              {t.rich("prompt.currentPlan", {
                plan: currentPlan,
                strong: (chunks) => (
                  <span className="font-medium text-foreground">{chunks}</span>
                ),
              })}
            </p>
          ) : null}
          <Button
            size={compact ? "sm" : "default"}
            className="w-full"
            render={<Link href={featureGatingConfig.upgradeHref} />}
            nativeButton={false}
          >
            {t("prompt.cta", { plan: requiredPlan })}
            <ArrowUpRight className="ml-2 size-4" />
          </Button>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

/**
 * The quietest of the three gating densities: one row, for a control
 * that is present but unavailable — a disabled toggle, a menu item a
 * plan doesn't include. Use `UpgradePrompt` when the gate replaces
 * real content, and this when it only annotates it.
 */

import { ArrowUpRight, Lock } from "lucide-react";
import { useTranslations } from "next-intl";

import { Link } from "@/i18n/navigation";
import { Button } from "@/components/ui/button";
import { featureGatingConfig } from "@/lib/feature-gating-config";

interface InlineUpgradeBannerProps {
  /** Display name of the gated feature, already localized. */
  feature: string;
  /** Display name of the plan that unlocks it, already localized. */
  requiredPlan: string;
  /** Overrides the default sentence entirely. */
  message?: string;
}

export function InlineUpgradeBanner({
  feature,
  requiredPlan,
  message,
}: InlineUpgradeBannerProps) {
  const t = useTranslations("feature-gating");

  return (
    <div className="flex items-center gap-3 rounded-lg border bg-muted/50 p-3">
      <span className="flex size-8 shrink-0 items-center justify-center rounded-full bg-muted">
        <Lock className="size-4 text-muted-foreground" aria-hidden />
      </span>
      <p className="flex-1 text-sm text-muted-foreground">
        {message ?? t("inline.message", { feature, plan: requiredPlan })}
      </p>
      <Button
        size="sm"
        variant="outline"
        render={<Link href={featureGatingConfig.upgradeHref} />}
        nativeButton={false}
      >
        {t("inline.cta")}
        <ArrowUpRight className="ml-2 size-3" />
      </Button>
    </div>
  );
}

"use client";

/**
 * Approaching-the-limit banner for a metered action.
 *
 * Renders nothing below the warning threshold, muted between it and
 * the urgent one, destructive above. Thresholds live in
 * `@/lib/feature-gating-config`.
 *
 * The copy is this item's own, computed from `remaining`, rather than
 * the `warning` string `@intelligo-dev/billing` returns: that string is
 * produced by a package that cannot know the caller's locale. Pass
 * `message` to override.
 */

import { AlertTriangle } from "lucide-react";
import { useTranslations } from "next-intl";

import type { FeatureQuotaResult } from "@intelligo-dev/billing";
import { cn } from "@/lib/utils";
import { featureGatingConfig } from "@/lib/feature-gating-config";

interface QuotaWarningProps {
  quota: FeatureQuotaResult;
  /** Overrides the computed sentence. */
  message?: string;
  className?: string;
}

export function QuotaWarning({ quota, message, className }: QuotaWarningProps) {
  const t = useTranslations("feature-gating");
  const { warnAtPercent, urgentAtPercent } = featureGatingConfig;

  if (quota.percentage < warnAtPercent) return null;

  const isUrgent = quota.percentage >= urgentAtPercent;

  return (
    <div
      role="status"
      className={cn(
        "flex items-center gap-2 rounded-lg border px-3 py-2 text-sm",
        isUrgent
          ? "border-destructive/20 bg-destructive/10 text-destructive"
          : "border-border bg-muted text-foreground",
        className
      )}
    >
      <AlertTriangle className="size-4 shrink-0" aria-hidden />
      <span>
        {message ??
          (quota.remaining > 0
            ? t("quota.remaining", { count: quota.remaining })
            : t("quota.exhausted"))}
      </span>
    </div>
  );
}

"use client";

/**
 * The modal shown when a metered action is refused mid-flow (unlike
 * `QuotaWarning`, which appears before the limit). It says what ran
 * out, offers the plans passed in, and can always be dismissed.
 */

import { ArrowRight, Sparkles } from "lucide-react";
import { useFormatter, useTranslations } from "next-intl";

import type { FeatureQuotaResult } from "@intelligo-dev/billing";
import type { PlanConfig } from "@intelligo-dev/billing/plans";

import { Link } from "@/i18n/navigation";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { CURRENCY } from "@/lib/billing-config";
import { featureGatingConfig } from "@/lib/feature-gating-config";

interface QuotaLimitDialogProps {
  open: boolean;
  onClose: () => void;
  quota: FeatureQuotaResult;
  /**
   * Plans to offer, already filtered to ones above the caller's
   * current plan. Resolve them on the server (`getPlanConfigs`) and
   * pass them down — this component does not decide who is eligible
   * for what.
   */
  upgradeOptions: PlanConfig[];
  /** Localized name of the action that ran out (e.g. "Messages"). */
  actionLabel?: string;
}

export function QuotaLimitDialog({
  open,
  onClose,
  quota,
  upgradeOptions,
  actionLabel,
}: QuotaLimitDialogProps) {
  const t = useTranslations("feature-gating");
  const format = useFormatter();

  const price = (plan: PlanConfig) => {
    const amount = plan.priceMonthly ?? plan.priceOneTime;
    if (!amount) return null;
    return format.number(amount, {
      style: "currency",
      currency: CURRENCY,
      maximumFractionDigits: 0,
    });
  };

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <div className="mx-auto mb-2 flex size-12 items-center justify-center rounded-full bg-primary/10">
            <Sparkles className="size-6 text-primary" aria-hidden />
          </div>
          <DialogTitle className="text-center">
            {t("limitDialog.title", {
              action: actionLabel ?? t("limitDialog.genericAction"),
            })}
          </DialogTitle>
          <DialogDescription className="text-center">
            {t("limitDialog.description", {
              used: quota.used,
              limit: quota.limit,
            })}
          </DialogDescription>
        </DialogHeader>

        <div className="mt-4 space-y-3">
          {upgradeOptions.map((plan, index) => {
            const amount = price(plan);
            return (
              <Button
                key={plan.slug}
                size="lg"
                variant={index === 0 ? "default" : "outline"}
                className="w-full"
                render={<Link href={featureGatingConfig.upgradeHref} />}
                nativeButton={false}
              >
                {amount
                  ? t("limitDialog.planCta", {
                      plan: plan.name,
                      price: amount,
                    })
                  : t("limitDialog.planCtaNoPrice", { plan: plan.name })}
                <ArrowRight className="ml-2 size-4" />
              </Button>
            );
          })}

          <Button variant="ghost" className="w-full" onClick={onClose}>
            {t("limitDialog.dismiss")}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

/**
 * Preview paywall: shows that the content exists and is worth having,
 * without giving it away. The children render blurred, inert and
 * unselectable behind an overlay with the upgrade CTA.
 *
 * The blur is presentation, not protection: the content is in the DOM.
 * Anything that must not reach an unentitled browser belongs behind
 * `FeatureGate` on the server instead.
 */

import { ArrowRight, Lock } from "lucide-react";
import { useTranslations } from "next-intl";

import { Link } from "@/i18n/navigation";
import { Button } from "@/components/ui/button";
import { featureGatingConfig } from "@/lib/feature-gating-config";

interface PaywallBlurProps {
  children: React.ReactNode;
  isLocked: boolean;
  /** Heading over the blur; falls back to this item's copy. */
  title?: string;
  /** Sentence under the heading. */
  description?: string;
  /** CTA label; falls back to this item's copy. */
  ctaLabel?: string;
}

export function PaywallBlur({
  children,
  isLocked,
  title,
  description,
  ctaLabel,
}: PaywallBlurProps) {
  const t = useTranslations("feature-gating");

  if (!isLocked) return <>{children}</>;

  return (
    <div className="relative">
      <div aria-hidden className="pointer-events-none select-none blur-sm">
        {children}
      </div>

      <div className="absolute inset-0 flex items-center justify-center rounded-xl bg-background/60 backdrop-blur-[2px]">
        <div className="max-w-sm p-6 text-center">
          <div className="mx-auto mb-4 flex size-12 items-center justify-center rounded-full bg-primary/10">
            <Lock className="size-5 text-primary" aria-hidden />
          </div>
          <h3 className="text-lg font-semibold">
            {title ?? t("paywall.title")}
          </h3>
          <p className="mt-2 text-sm text-muted-foreground">
            {description ?? t("paywall.description")}
          </p>
          <Button
            size="lg"
            className="mt-4"
            render={<Link href={featureGatingConfig.upgradeHref} />}
            nativeButton={false}
          >
            {ctaLabel ?? t("paywall.cta")}
            <ArrowRight className="ml-2 size-4" />
          </Button>
        </div>
      </div>
    </div>
  );
}

/**
 * Feature catalogue — consumer-owned.
 *
 * Which features exist, what to call them, and which plan unlocks them
 * is product data, not framework data: `@intelligo-dev/billing` answers
 * "is this workspace entitled to feature X" (`hasFeature`), and this
 * file answers "what should we say when it isn't".
 *
 * `labelKey` and `descriptionKey` are fully-qualified message keys
 * resolved namespace-less (the `chatConfig.starters` contract), so a
 * feature's copy lives in your own message files. `requiredPlan` is
 * the plan slug that unlocks it — rendered through the plan catalogue
 * registered by your composition root, so the name a user sees stays
 * in one place.
 *
 * A feature missing from this map still gates correctly; it just falls
 * back to generic copy.
 */

export interface FeatureDescriptor {
  /** Fully-qualified message key for the feature's display name. */
  labelKey: string;
  /** Plan slug that unlocks it (must exist in your plan catalogue). */
  requiredPlan: string;
  /** Fully-qualified message key for a longer explanation. */
  descriptionKey?: string;
}

/**
 * Example, once your product has features to gate:
 *
 *   export const featureCatalog: Record<string, FeatureDescriptor> = {
 *     file_uploads: {
 *       labelKey: "features.fileUploads.label",
 *       descriptionKey: "features.fileUploads.description",
 *       requiredPlan: "pro",
 *     },
 *   };
 */
export const featureCatalog: Record<string, FeatureDescriptor> = {};

/**
 * Feature-gating configuration — consumer-owned.
 *
 * `upgradeHref`: where every gating surface sends the user. Defaults
 * to the billing settings page (the `billing-settings` item's route),
 * which is where a plan change actually happens; point it at
 * `/pricing` if your product prefers the comparison first.
 *
 * `warnAtPercent` / `urgentAtPercent`: when `QuotaWarning` starts
 * showing, and when it escalates. Below the first, it renders nothing.
 */

export interface FeatureGatingConfig {
  upgradeHref: string;
  warnAtPercent: number;
  urgentAtPercent: number;
}

export const featureGatingConfig: FeatureGatingConfig = {
  upgradeHref: "/settings/billing",
  warnAtPercent: 80,
  urgentAtPercent: 95,
};

{
  "genericFeature": "This feature",
  "genericPlan": "a paid plan",
  "prompt": {
    "title": "{feature} requires {plan}",
    "description": "{feature} is included from the {plan} plan up. Upgrade to unlock it.",
    "currentPlan": "You're currently on the <strong>{plan}</strong> plan.",
    "cta": "Upgrade to {plan}"
  },
  "inline": {
    "message": "Upgrade to {plan} to use {feature}",
    "cta": "Upgrade"
  },
  "quota": {
    "remaining": "{count, plural, one {# use left} other {# uses left}}",
    "exhausted": "You've used everything included in your plan."
  },
  "paywall": {
    "title": "See the full version",
    "description": "Upgrade to read this in full, and to keep everything you generate.",
    "cta": "Upgrade"
  },
  "limitDialog": {
    "title": "You've used all your {action}",
    "genericAction": "included usage",
    "description": "You've used {used} of {limit}. Upgrading raises the limit right away.",
    "planCta": "Upgrade to {plan} — {price}",
    "planCtaNoPrice": "Upgrade to {plan}",
    "dismiss": "Not now"
  }
}
